def algorithm(func, dim, lb, ub, budget, rng):
    N = 50  # population size
    T = 1000  # number of iterations
    alpha = 1e-2  # learning rate
    beta = 0.9   # cooling factor for simulated annealing
    x_best = np.random.uniform(lb, ub, (dim))
    best_val = func(x_best)

    for t in range(T):
        if rng.random() < 0.1:
            T_new = max(1e-3, beta * T)  # adjust temperature based on cooling factor
        else:
            T_new = T

        candidates = np.clip(np.multiply(rng.normal(size=(N, dim)), alpha) + x_best,
                             lb, ub)

        vals = func(candidates)

        for i in range(N):
            if rng.random() < np.exp((best_val - vals[i]) / T_new):
                x_best = candidates[i]
                best_val = min(best_val, vals[i])

    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.minimum(np.maximum(x, lb), ub)

    x = np.random.uniform(lb, ub, size=dim)
    distribution = {'mu': 0, 'sigma': 1.0}
    archive = [x]
    for _ in range(budget):
        candidates = []
        for _ in range(4 * dim):
            new_x = np.clip(x + np.random.normal(size=x.shape) * distribution['sigma'] + distribution['mu'], lb, ub)
            candidates.append(new_x)
        candidates = np.array(candidates)
        candidates = clip(candidates)
        f_candidates = func(candidates)

        best_candidate_idx = np.argmin(f_candidates)
        new_best_x = candidates[best_candidate_idx]

        distribution['sigma'] *= 0.5 if np.mean(np.log(f_candidates)) > 10 else 1.2
        x = new_best_x

        archive.append(x)
    return clip(np.array(archive).mean(axis=0))

